#![cfg(feature="player")]
#[path="support/audio_transitions.rs"]mod transitions;
#[path="support/rational_audio_seek.rs"]mod rational;
use fvid::{audio::AudioStream,playback_mp4_audio::Mp4AudioReader};
use std::{io::Cursor,time::Duration,sync::{Arc,Mutex}};
use rational::{Packet,collect,exact,suffix,anchor};
fn root()->std::path::PathBuf{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/playback-errors/mp4-g711-seek")}
fn bytes(n:&str)->Vec<u8>{std::fs::read(root().join(n)).unwrap()}
fn cases()->Vec<serde_json::Value>{serde_json::from_slice::<serde_json::Value>(&bytes("manifest.json")).unwrap()["cases"].as_array().unwrap().clone()}
fn open(n:&str)->Mp4AudioReader<Cursor<Vec<u8>>>{Mp4AudioReader::open(Cursor::new(bytes(n)),Default::default()).unwrap()}
fn end(c:&serde_json::Value)->(u128,u128){(c["end_num"].as_u64().unwrap()as u128,c["end_den"].as_u64().unwrap()as u128)}
fn oracle(c:&serde_json::Value)->Vec<Packet>{vec![Packet{rate:c["rate"].as_u64().unwrap()as u32,channels:c["channels"].as_u64().unwrap()as u16,num:0,den:1,data:bytes(c["oracle"].as_str().unwrap())}]}
#[test]fn independent_wave_oracles_and_short_video_are_valid(){for c in cases(){let data=bytes(c["wave"].as_str().unwrap());let mut w=fvid::playback_wav::WavAudioReader::open(data.as_slice(),Default::default()).unwrap();if !c["edited"].as_bool().unwrap(){exact(&collect(&mut w),&oracle(&c),"independent G711 wave");}let mut v=fvid::playback_native::NativeReader::software(Cursor::new(bytes(c["file"].as_str().unwrap())),32<<20).unwrap();for _ in 0..6{assert_eq!(v.read_frame_raw().unwrap().unwrap().into_rgb(32<<20).unwrap(),vec![130;16*16*3]);}assert!(v.read_frame_raw().unwrap().is_none());}}
#[test]fn quicktime_g711_playback_and_precise_seek_match_independent_pcm(){for c in cases(){let n=c["file"].as_str().unwrap();let wanted=oracle(&c);let mut r=open(n);assert_eq!((r.sample_rate(),r.channels()),(wanted[0].rate,wanted[0].channels));assert_eq!(r.duration(),Some(rational::duration(end(&c).0,end(&c).1)));exact(&collect(&mut r),&wanted,n);let mut qs:Vec<_>=c["queries_ns"].as_array().unwrap().iter().map(|n|Duration::from_nanos(n.as_u64().unwrap())).collect();qs.push(Duration::MAX);for t in qs{let expected=suffix(&wanted,t,end(&c));let at=r.seek_time(t);exact(&collect(&mut r),&expected,&format!("{n}:{t:?}"));assert_eq!(r.time_of(at),anchor(&expected,end(&c)));}r.seek_to(0);exact(&collect(&mut r),&wanted,"raw reset");}}
#[test]fn actual_g711_worker_keeps_native_pcm_timebases_and_flush_anchor(){use fvid::audio_thread::AudioPlayback;use transitions::{Capture,Trace,ended};for c in cases(){let n=c["file"].as_str().unwrap();let t=Duration::from_nanos(500001);let wanted=suffix(&oracle(&c),t,end(&c));let raw=Arc::new(Mutex::new(rational::RawTrace::default()));let captured=raw.clone();let trace=Arc::new(Mutex::new(Trace::default()));let mut w=AudioPlayback::start(Box::new(open(n)),move||Box::new(rational::RawCapture{inner:Capture::new(trace),raw:captured}));w.seek(t);w.play();ended(&w,w.generation());let guard=raw.lock().unwrap();exact(&guard.packets,&wanted,n);assert_eq!(guard.anchors,vec![anchor(&wanted,end(&c))]);}}
#[test]fn owned_g711_float32_and_float64_exports_match_independent_levels(){for c in cases(){let n=c["file"].as_str().unwrap();let input=bytes(n);let expected=oracle(&c);for interval in [None,Some((Duration::from_nanos(500001),Duration::from_nanos(10000001)))]{let stride=usize::from(expected[0].channels)*4;let rate=u128::from(expected[0].rate);let range=if let Some((a,b))=interval{let at=|t:Duration|((t.as_nanos()*rate).div_ceil(1_000_000_000)as usize*stride).min(expected[0].data.len());at(a)..at(b)}else{0..expected[0].data.len()};let want=&expected[0].data[range];let mut out=Vec::new();let stats=fvid_media::owned_mp4_audio::decode_mp4_audio_pcm(Cursor::new(&input),&mut out,interval,&Default::default()).unwrap();assert_eq!(out,want,"{n}:f32");assert_eq!(stats.sample_frames,want.len()as u64/stride as u64);out.clear();fvid_media::owned_mp4_audio::decode_mp4_pcm_f64(Cursor::new(&input),&mut out,interval,&Default::default()).unwrap();let f64bytes:Vec<_>=want.chunks_exact(4).flat_map(|b|(f32::from_le_bytes(b.try_into().unwrap())as f64).to_le_bytes()).collect();assert_eq!(out,f64bytes,"{n}:f64");}}}
#[test]fn uniform_g711_keeps_index_budget_in_frames_without_losing_coded_bytes(){for c in cases().into_iter().filter(|c|c["uniform"]==true && c["edited"]==false){let mut limits=fvid::container::mp4::Limits::default();limits.samples=16;let mut r=Mp4AudioReader::open(Cursor::new(bytes(c["file"].as_str().unwrap())),limits).unwrap();assert_eq!(r.track().samples.cost(),1);assert_eq!(r.track().samples.len(),768);exact(&collect(&mut r),&oracle(&c),"uniform sample budget");}}
#[test]fn malformed_channel_and_full_packet_budget_refuse_specifically(){let mut r=open("orphan-channel.mov");let mut decoder=r.make_decoder().unwrap();let p=match r.next_step().unwrap().unwrap(){fvid::audio::AudioStep::Encoded(p)=>p,_=>panic!("expected coded G711")};let error=decoder.decode_packet(&p.data,r.decoder_stamp(&p),p.duration as u64).err().expect("orphan channel must refuse before output");assert!(error.to_string().contains("incomplete channel frame"),"{error}");let mut r=open("orphan-channel.mov");r.seek_time(Duration::from_nanos(500001));let error=r.next_step().err().expect("native seek must retain coded alignment");assert!(error.to_string().contains("incomplete MP4 coded audio block"),"{error}");let mut limits=fvid::container::mp4::Limits::default();limits.packet_bytes=128;let mut r=Mp4AudioReader::open(Cursor::new(bytes("alaw-48000-2ch-classic.mov")),limits).unwrap();let error=r.next_step().err().expect("full coded packet must retain admission");assert!(error.to_string().contains("MP4 packet exceeds budget"),"{error}");}
#[test]fn public_planning_native_geometry_and_wave_publication_preserve_g711_pcm(){struct OwnedDir(std::path::PathBuf);impl Drop for OwnedDir{fn drop(&mut self){std::fs::remove_dir_all(&self.0).unwrap();}}let path=std::env::temp_dir().join(format!("fvid-g711-public-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir(&path).unwrap();let temp=OwnedDir(path);for c in cases(){let n=c["file"].as_str().unwrap();let source=root().join(n);let expected=oracle(&c);let name=if c["codec"]=="alaw"{"pcm_alaw"}else{"pcm_mulaw"};let info=fvid::native_media::audio_source_info_selected(&source,None).unwrap();assert_eq!((info.codec,info.sample_rate,info.channels),(name,expected[0].rate,expected[0].channels));let plan=fvid_media::plan_decode_audio(&source,&Default::default(),&Default::default()).unwrap();assert_eq!(plan.streams[0].codec,name);let dest=temp.0.join(format!("{n}.wav"));fvid_media::decode_audio(&source,&dest,&Default::default()).unwrap();let wave=std::fs::read(&dest).unwrap();let parsed=fvid_media::owned_wave_inspect::inspect(&mut Cursor::new(&wave),None).unwrap();assert_eq!((parsed.sample_rate,parsed.channels,parsed.sample_frames),(expected[0].rate,expected[0].channels,c["frames"].as_u64().unwrap()));let pcm=&wave[parsed.data_offset as usize..(parsed.data_offset+u64::from(parsed.data_bytes))as usize];assert!(parsed.float);assert_eq!(parsed.bits_per_sample,64);let expected64:Vec<_>=expected[0].data.chunks_exact(4).flat_map(|b|(f32::from_le_bytes(b.try_into().unwrap())as f64).to_le_bytes()).collect();assert_eq!(pcm,expected64,"{n}:published float64 wave");}}
